root.addEventListener('input',e=>{if(!e.target.matches('[data-cat-search]'))return;catalogManagementState.search=e.target.value;catalogManagementState.page=1;render(true)});
root.addEventListener('change',e=>{if(e.target.matches('[data-cat-status]')){catalogManagementState.status=e.target.value;catalogManagementState.page=1;render()}if(e.target.matches('[data-cat-filter]')){catalogManagementState.filters[e.target.dataset.catFilter]=e.target.value;catalogManagementState.page=1;render()}if(e.target.matches('[data-suite-page-size]')&&(pathOf().startsWith('/app/catalog/')||pathOf()==='/app/ecommerce/products')){catalogManagementState.pageSize=Number(e.target.value)||5;catalogManagementState.page=1;render()}});
root.addEventListener('click',e=>{const page=e.target.closest('[data-suite-page]');if(page&&(pathOf().startsWith('/app/catalog/')||pathOf()==='/app/ecommerce/products')&&!page.disabled){catalogManagementState.page=Number(page.dataset.suitePage)||1;render();return}const tab=e.target.closest('[data-cat-tab]');if(tab){catalogManagementState.tab=tab.dataset.catTab;catalogManagementState.page=1;render();return}if(e.target.closest('[data-cat-reset]')){catalogManagementState.search='';catalogManagementState.status='';catalogManagementState.filters={};catalogManagementState.page=1;render();return}const create=e.target.closest('[data-cat-new]');if(create){const kind=create.dataset.catNew;if(['types','categories','brands'].includes(kind)){const titles={types:'Product Type',categories:'Category',brands:'Brand'},fieldsets={types:[['Name','name',''],['Slug','slug','']],categories:[['Name','name',''],['Slug','slug',''],['Parent category','parent','—']],brands:[['Name','name',''],['Slug','slug',''],['Logo image','logo','', 'file']]};activeAction=`Add ${titles[kind]}`;activeOverlayClass='cat-form-overlay';activeOverlayHTML=`<form data-cat-quick-form="${kind}" class="cat-quick-form">${fieldsets[kind].map(([label,name,value,type])=>`<label>${label} *<input name="${name}" type="${type||'text'}" value="${value}"></label>`).join('')}<label class="cat-check"><input type="checkbox" name="active" checked><span>Active</span></label><button class="btn primary">Save ${titles[kind]}</button></form>`;drawer='original';render();return}const route=kind==='tax-class'?'tax-classes':kind==='tax-rule'?'tax-rules':'tax-hs-code-mappings';location.hash=`#/app/catalog/${route}/new`;return}const open=e.target.closest('[data-cat-open]');if(open){const key=open.dataset.catOpen,id=open.dataset.catId;if(['pricing','taxClasses','taxRules','hs'].includes(key)){const base=key==='pricing'?'pricing-rules':key==='taxClasses'?'tax-classes':key==='taxRules'?'tax-rules':'tax-hs-code-mappings';location.hash=`#/app/catalog/${base}/${id}`;return}const row=catRowsFor(key).find(x=>x.id===id);if(!row)return;activeAction=`${key==='types'?'Product type':key==='categories'?'Category':'Brand'} details`;activeOverlayHTML=`<div class="cat-quick-detail"><span>${row.id}</span><h3>${catEsc(row.name)}</h3><p>${row.products??0} products · ${row.status}</p><dl>${Object.entries(row).filter(([k])=>!['id','name','initials'].includes(k)).map(([k,v])=>`<div><dt>${catEsc(k)}</dt><dd>${catEsc(v)}</dd></div>`).join('')}</dl></div>`;activeOverlayClass='cat-form-overlay';drawer='original';render();return}if(e.target.closest('[data-cat-view]')){catalogManagementState.view=catalogManagementState.view==='cards'?'list':'cards';render();return}});
root.addEventListener('submit',e=>{const form=e.target.closest('[data-cat-form]');if(!form)return;e.preventDefault();const kind=form.dataset.catForm,payload=Object.fromEntries(new FormData(form)),route=kind==='tax-class'?'tax-classes':kind==='tax-rule'?'tax-rules':kind==='hs'?'tax-hs-code-mappings':'pricing-rules',ids={ 'tax-class':'TAX','tax-rule':'TR','hs':'HS','pricing-rule':'PR' },arrays={'tax-class':catalogTaxClasses,'tax-rule':catalogTaxRules,'hs':catalogHsMappings,'pricing-rule':catalogPricingRules},prefix=ids[kind],rows=arrays[kind],idMatch=new RegExp(`${prefix}-\\d+`).exec(pathOf()),record=idMatch?rows.find(r=>r.id===idMatch[0]):null,entry={...payload,status:payload.active?'Active':'Inactive'};for(const field of ['rate','priority','value','usage','minimumCart'])if(entry[field]!==undefined)entry[field]=Number(entry[field])||0;if(kind==='tax-class'){entry.isDefault=Boolean(payload.isDefault);entry.updated='25 Sep 2026'}if(kind==='tax-rule'){entry.name=`${payload.country||'Tax'} ${payload.type||'rule'}`;entry.updated='25 Sep 2026'}if(kind==='hs'){entry.name=`${payload.code} · ${payload.category}`}if(kind==='pricing-rule'){entry.name=payload.name;entry.coupon=payload.coupon||'—';entry.starts=payload.starts;entry.ends=payload.ends;entry.stack='Exclusive'}if(record)Object.assign(record,entry);else{entry.id=`${prefix}-${String((Number(rows.at(-1).id.match(/\d+/)?.[0])||0)+1).padStart(prefix==='PR'||prefix==='TR'?4:3,'0')}`;rows.push(entry)}flash(`${form.querySelector('.pm-card h2')?.textContent||kind} saved to this preview.`);location.hash=`#/app/catalog/${route}`});
root.addEventListener('submit',e=>{const form=e.target.closest('[data-cat-quick-form]');if(!form)return;e.preventDefault();const kind=form.dataset.catQuickForm,payload=Object.fromEntries(new FormData(form));if(kind==='types')catalogTypes.push({id:`TYP-${String(catalogTypes.length+1).padStart(3,'0')}`,name:payload.name,slug:payload.slug,status:payload.active?'Active':'Inactive',products:0});if(kind==='categories')catalogCategories.push({id:`CAT-${String(catalogCategories.length+1).padStart(3,'0')}`,name:payload.name,slug:payload.slug,parent:payload.parent||'—',type:'Apparel',products:0,status:payload.active?'Active':'Inactive'});if(kind==='brands')catalogBrands.push({id:`BR-${String(catalogBrands.length+1).padStart(3,'0')}`,name:payload.name,slug:payload.slug,products:0,status:payload.active?'Active':'Inactive',initials:payload.name.split(' ').map(x=>x[0]).join('').slice(0,2)});drawer='';flash('Catalog record saved to this preview.')});
